for (const file of suites) {
  // 每个套件在独立的临时 DSH_HOME 里跑
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'dsh-'))
  const env = { ...process.env, DSH_HOME: tmp }
  const r = spawnSync(process.execPath, [file], { env, encoding: 'utf8' })
  if (r.status !== 0) { failed++; console.log(`  FAIL ${file}  ${String(r.stderr).split('\n').find((l) => /Error/.test(l)) || ''}`) }
  else console.log(`  PASS ${file}`)
  fs.rmSync(tmp, { recursive: true, force: true })
}
console.log(`  合计: ${suites.length - failed} 通过 / ${failed} 失败`)
process.exit(failed ? 1 : 0)
